<?= $this->extend('layouts/customer') ?><?= $this->section('content') ?><h1 class="h2 mb-4"><?= esc($category['name']??'Products') ?></h1><?php if(!empty($category['description'])): ?><p class="lead mb-4"><?= esc($category['description']) ?></p><?php endif ?><div class="row g-4"><?php foreach($products as $p): ?><?php $price=$pricing->effectivePrice($p);$state=$inventory->stockStatus((int)$p['stock_quantity'],(int)$p['low_stock_threshold']); ?><div class="col-sm-6 col-lg-4 col-xl-3"><div class="card h-100 overflow-hidden"><?php if($p['main_image']): ?><img class="product-image w-100" src="<?= base_url($p['main_image']) ?>" alt="<?= esc($p['name']) ?>"><?php else: ?><div class="product-image d-grid place-items-center"></div><?php endif ?><div class="card-body"><h2 class="h5"><a class="text-dark text-decoration-none" href="<?= url_to('catalog.product',$p['slug']) ?>"><?= esc($p['name']) ?></a></h2><div class="fw-bold text-success">৳<?= number_format($price,2) ?> <?php if($p['sale_price']!==null): ?><del class="small text-muted fw-normal">৳<?= number_format($p['regular_price'],2) ?></del><?php endif ?></div><span class="badge mt-2 text-bg-<?= $state==='in_stock'?'success':($state==='low_stock'?'warning':'danger') ?>"><?= ucwords(str_replace('_',' ',$state)) ?></span></div></div></div><?php endforeach ?><?php if(!$products): ?><p class="text-muted">No products are available.</p><?php endif ?></div><div class="mt-4"><?= $pager->links() ?></div><?= $this->endSection() ?>
